// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font at module level to guarantee availability before frame 0
const { fontFamily: interFamily } = loadInter();



export type GraphAnimationProps = Record<string, any>;

const GraphAnimation: React.FC<GraphAnimationProps> = ({
  backgroundColor = "#0F172A", // Dark slate
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Strength Curve: Reps vs. Weight",
  xAxisLabel = "Weight (lbs)",
  yAxisLabel = "Repetitions",
  maxWeight = 315,
  maxReps = 20,
  lineColor = "#38BDF8", // Light blue
  dotColor = "#F43F5E", // Rose/Red
  axisColor = "#475569", // Slate gray
  textColor = "#F8FAFC", // Off-white
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const paddingX = width * 0.12; // ~230px
  const paddingY = height * 0.18; // ~194px
  const graphX = paddingX;
  const graphY = paddingY;
  const graphWidth = width - paddingX * 2;
  const graphHeight = height - paddingY * 1.6; // Leave more room at bottom for X label

  // Time & Animation phases
  const totalFrames = Math.round(fps * durationInSeconds);
  const startDrawFrame = Math.round(fps * 0.8); // Start drawing at 0.8s
  const endDrawFrame = totalFrames - Math.round(fps * 1.5); // Finish drawing 1.5s before end

  // Overall intro spring for axes and labels
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Progress of the line drawing (0 to 1)
  const drawProgress = interpolate(
    frame,
    [startDrawFrame, endDrawFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );

  // --- Path Generation & Math ---
  // To create a realistic "reps drop as weight increases" curve, we use an exponential/power decay.
  // normalized R = (1 - t)^power. Higher power = sharper initial drop.
  const curvePower = 2.5;

  let pathD = `M ${graphX} ${graphY}`;
  const steps = 100;
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const x = graphX + t * graphWidth;
    const rNorm = Math.pow(1 - t, curvePower);
    const y = graphY + (1 - rNorm) * graphHeight;
    pathD += ` L ${x} ${y}`;
  }

  // --- Current Point Calculations ---
  // Ensure the dot exactly follows the generated path mathematically
  const currentX = graphX + drawProgress * graphWidth;
  const currentRNorm = Math.pow(1 - drawProgress, curvePower);
  const currentY = graphY + (1 - currentRNorm) * graphHeight;

  // Data values for the tooltip
  const currentWeight = interpolate(drawProgress, [0, 1], [0, maxWeight]);
  // Reps formula: 1 is minimum reps at max weight.
  const currentReps = 1 + (maxReps - 1) * currentRNorm;

  // Opacity for the line and dot based on draw progress
  const lineOpacity = interpolate(frame, [startDrawFrame - 10, startDrawFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
        transition: "none",
      }}
    >
      {/* Title */}
      <h1
        style={{
          position: "absolute",
          top: height * 0.06,
          left: 0,
          width: "100%",
          textAlign: "center",
          fontSize: 56,
          fontWeight: 800,
          margin: 0,
          opacity: introSpring,
          transform: `translateY(${interpolate(introSpring, [0, 1], [-20, 0])}px)`,
          transition: "none",
        }}
      >
        {title}
      </h1>

      {/* Graph Area Container (SVG) */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        {/* Defs for clip path to animate the line drawing smoothly without path lengths */}
        <defs>
          <clipPath id="reveal-clip">
            <rect
              x={graphX - 20}
              y={graphY - 20}
              width={(currentX - graphX) + 20} // +20 accommodates stroke width at the leading edge
              height={graphHeight + 40}
            />
          </clipPath>
        </defs>

        {/* Grid Lines (Horizontal) */}
        {[0, 1, 2, 3, 4].map((i) => {
          const yPos = graphY + (i / 4) * graphHeight;
          return (
            <line
              key={`h-grid-${i}`}
              x1={graphX}
              y1={yPos}
              x2={graphX + graphWidth}
              y2={yPos}
              stroke={axisColor}
              strokeWidth={2}
              strokeDasharray="8 8"
              opacity={introSpring * 0.3}
            />
          );
        })}

        {/* Grid Lines (Vertical) */}
        {[1, 2, 3, 4].map((i) => {
          const xPos = graphX + (i / 4) * graphWidth;
          return (
            <line
              key={`v-grid-${i}`}
              x1={xPos}
              y1={graphY}
              x2={xPos}
              y2={graphY + graphHeight}
              stroke={axisColor}
              strokeWidth={2}
              strokeDasharray="8 8"
              opacity={introSpring * 0.3}
            />
          );
        })}

        {/* Axes */}
        <path
          d={`M ${graphX} ${graphY} L ${graphX} ${graphY + graphHeight} L ${graphX + graphWidth} ${graphY + graphHeight}`}
          fill="none"
          stroke={axisColor}
          strokeWidth={6}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ opacity: introSpring }}
        />

        {/* The Animated Data Curve */}
        <path
          d={pathD}
          fill="none"
          stroke={lineColor}
          strokeWidth={10}
          strokeLinecap="round"
          strokeLinejoin="round"
          clipPath="url(#reveal-clip)"
          style={{ opacity: lineOpacity }}
        />

        {/* The Leading Dot */}
        {drawProgress > 0 && (
          <circle
            cx={currentX}
            cy={currentY}
            r={16}
            fill={dotColor}
            stroke={backgroundColor}
            strokeWidth={4}
            style={{ opacity: lineOpacity }}
          />
        )}
      </svg>

      {/* Axis Labels (HTML for easier typography) */}
      <div
        style={{
          position: "absolute",
          top: graphY + graphHeight + 40,
          left: graphX,
          width: graphWidth,
          textAlign: "center",
          fontSize: 32,
          fontWeight: 600,
          color: axisColor,
          opacity: introSpring,
        }}
      >
        {xAxisLabel}
      </div>
      <div
        style={{
          position: "absolute",
          top: graphY + graphHeight / 2,
          left: graphX - 120, // Offset to the left of Y axis
          transform: "translate(-50%, -50%) rotate(-90deg)",
          fontSize: 32,
          fontWeight: 600,
          color: axisColor,
          opacity: introSpring,
        }}
      >
        {yAxisLabel}
      </div>

      {/* Axis Min/Max Markers */}
      <div style={{ position: "absolute", top: graphY - 15, left: graphX - 80, fontSize: 24, fontWeight: 700, opacity: introSpring, color: textColor }}>
        {maxReps}
      </div>
      <div style={{ position: "absolute", top: graphY + graphHeight + 15, left: graphX + graphWidth - 20, fontSize: 24, fontWeight: 700, opacity: introSpring, color: textColor }}>
        {maxWeight}
      </div>

      {/* Floating Tooltip Data Panel */}
      {drawProgress > 0 && (
        <div
          style={{
            position: "absolute",
            left: currentX,
            top: currentY,
            // Flip the tooltip to the left side if it gets too close to the right edge
            transform: `translate(${drawProgress > 0.75 ? "calc(-100% - 30px)" : "30px"}, -50%)`,
            backgroundColor: "rgba(15, 23, 42, 0.95)", // Matches default slate but opaque
            backdropFilter: "blur(10px)",
            border: `2px solid ${lineColor}`,
            padding: "24px 32px",
            borderRadius: "16px",
            boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
            display: "flex",
            flexDirection: "column",
            gap: "8px",
            opacity: lineOpacity,
            minWidth: 220,
            transition: "none", // Critical for remotion
          }}
        >
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 30 }}>
            <span style={{ fontSize: 24, color: axisColor, fontWeight: 600 }}>Weight</span>
            <span style={{ fontSize: 36, fontWeight: 800 }}>{Math.round(currentWeight)}</span>
          </div>
          <div style={{ height: 2, width: "100%", backgroundColor: axisColor, opacity: 0.3, margin: "8px 0" }} />
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 30 }}>
            <span style={{ fontSize: 24, color: axisColor, fontWeight: 600 }}>Reps</span>
            <span style={{ fontSize: 42, fontWeight: 900, color: dotColor }}>{Math.round(currentReps)}</span>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default GraphAnimation;